window.__PAGES=window.__PAGES||{};window.__PAGES["pages/settings-organization-general.html"]="<!-- Settings: Organisasi — Umum -->\n<style>\n.st-org-form label{display:block;font-size:13px;font-weight:500;margin-bottom:14px}\n.st-org-form label input,.st-org-form label select{display:block;width:100%;max-width:400px;padding:8px 10px;border:1px solid var(--border);border-radius:8px;margin-top:4px;font-size:13px;background:var(--bg)}\n.st-org-form label input:focus,.st-org-form label select:focus{outline:2px solid var(--accent);outline-offset:-1px;border-color:var(--accent)}\n.st-org-row{display:flex;justify-content:space-between;align-items:center;padding:10px 0;border-bottom:1px solid var(--border)}\n.st-org-row:last-child{border:none}\n.st-org-k{font-size:13px;color:var(--muted);min-width:160px}\n.st-org-v{font-size:14px;font-weight:600}\n</style>\n\n<div class=\"settings-layout\">\n  <aside class=\"settings-sidenav\" id=\"stNav\"></aside>\n  <div class=\"settings-body\">\n    <h2 style=\"margin-bottom:6px\">Pengaturan Umum</h2>\n    <p style=\"font-size:13px;color:var(--muted);margin-bottom:20px\">Informasi dasar organisasi Anda.</p>\n\n    <!-- View mode -->\n    <div class=\"card\" id=\"orgView\">\n      <div class=\"st-org-row\"><span class=\"st-org-k\">Nama Organisasi</span><span class=\"st-org-v\" id=\"ovName\"></span></div>\n      <div class=\"st-org-row\"><span class=\"st-org-k\">Industri</span><span class=\"st-org-v\" id=\"ovIndustry\"></span></div>\n      <div class=\"st-org-row\"><span class=\"st-org-k\">Zona Waktu</span><span class=\"st-org-v\" id=\"ovTz\"></span></div>\n      <div class=\"st-org-row\"><span class=\"st-org-k\">Bahasa</span><span class=\"st-org-v\" id=\"ovLang\"></span></div>\n      <div style=\"margin-top:14px\"><button class=\"btn primary\" onclick=\"toggleOrgEdit(true)\">✏ Edit</button></div>\n    </div>\n\n    <!-- Edit mode -->\n    <div class=\"card hide\" id=\"orgEdit\">\n      <div class=\"st-org-form\">\n        <label>Nama Organisasi<input type=\"text\" id=\"oeName\"></label>\n        <label>Industri<select id=\"oeIndustry\"><option>E-commerce</option><option>FinTech</option><option>Healthcare</option><option>Education</option><option>Lainnya</option></select></label>\n        <label>Zona Waktu<select id=\"oeTz\"><option>Asia/Jakarta</option><option>Asia/Makassar</option><option>Asia/Jayapura</option></select></label>\n        <label>Bahasa<select id=\"oeLang\"><option value=\"id\">Indonesia</option><option value=\"en\">English</option></select></label>\n        <div style=\"display:flex;gap:8px;margin-top:4px\">\n          <button class=\"btn primary\" onclick=\"saveOrg()\">💾 Simpan</button>\n          <button class=\"btn\" onclick=\"toggleOrgEdit(false)\">Batal</button>\n        </div>\n      </div>\n    </div>\n  </div>\n</div>\n\n<script>\n(function(){\n  // Settings sidenav\n  document.getElementById('stNav').innerHTML=renderSettingsNav('organization-general');\n\n  const o=DB.settings.org;\n  function renderView(){\n    document.getElementById('ovName').textContent=o.name;\n    document.getElementById('ovIndustry').textContent=o.industry;\n    document.getElementById('ovTz').textContent=o.timezone;\n    document.getElementById('ovLang').textContent=o.lang==='id'?'Indonesia':'English';\n  }\n  renderView();\n\n  window.toggleOrgEdit=function(on){\n    document.getElementById('orgView').classList.toggle('hide',on);\n    document.getElementById('orgEdit').classList.toggle('hide',!on);\n    if(on){\n      document.getElementById('oeName').value=o.name;\n      document.getElementById('oeIndustry').value=o.industry;\n      document.getElementById('oeTz').value=o.timezone;\n      document.getElementById('oeLang').value=o.lang;\n    }\n  };\n\n  window.saveOrg=function(){\n    o.name=document.getElementById('oeName').value.trim()||o.name;\n    o.industry=document.getElementById('oeIndustry').value;\n    o.timezone=document.getElementById('oeTz').value;\n    o.lang=document.getElementById('oeLang').value;\n    saveStore();\n    renderView();\n    toggleOrgEdit(false);\n    showToast('Pengaturan organisasi disimpan');\n  };\n})();\n</script>\n";
